use std::sync::Arc;
use std::sync::atomic::{AtomicUsize, Ordering::{Acquire, Release}};
use std::thread;

#[test]
fn two_increments() {
    let num = Arc::new(AtomicUsize::new(0));
    let ths: Vec<_> = (0..2).map(|_| {
        let num = num.clone();
        thread::spawn(move || {
            let curr = num.load(Acquire);   // step L: read
            num.store(curr + 1, Release);   // step S: write back
        })
    }).collect();
    for th in ths { th.join().unwrap(); }
    assert_eq!(2, num.load(Acquire));
}

