use loom::sync::atomic::AtomicUsize;
use loom::sync::Arc;
use loom::thread;
use std::sync::atomic::Ordering::Relaxed;

loom::model(|| {
    let x = Arc::new(AtomicUsize::new(0));
    let y = Arc::new(AtomicUsize::new(0));
    let th = { let (x, y) = (x.clone(), y.clone());
        thread::spawn(move || { x.store(1, Relaxed); y.load(Relaxed) }) };
    y.store(1, Relaxed);
    let b = x.load(Relaxed);
    let a = th.join().unwrap();
    // loom's own litmus test asserts that (a, b) == (0, 0) is observed
