struct Chan { data: loom::cell::UnsafeCell<usize>, guard: AtomicUsize }

impl Chan {
    fn set(&self) {
        self.data.with_mut(|v| unsafe { *v += 123 });
        self.guard.store(1, Release);
    }
    fn get(&self) {
        if self.guard.load(Acquire) == 0 { return; }  // remove this check and loom panics
        self.data.with(|v| unsafe { assert_eq!(*v, 123) });
    }
}

